import { Heart, Image, LayoutDashboard, ListChecks, LogOut, Package, ShoppingCart } from 'lucide-react'
import AvalAngadiLogo from '../../../assets/aval-angadi-logo.png'
const items = [[LayoutDashboard, 'Dashboard'], [Package, 'Products'], [Image, 'Image Gallery'], [ListChecks, 'Specifications'], [ShoppingCart, 'My Orders'], [Heart, 'My Wishlist']]
export default function VendorSidebar({ activePage, onNavigate, onAddProduct }) { return <aside className="vendor-sidebar"><div className="vendor-brand"><span style={{ border: 0 }}><img src={AvalAngadiLogo} alt="Aval Angadi" style={{ width: '34px', height: '34px', objectFit: 'contain' }} /></span><div><strong>AVAL ANGADI</strong><small>Seller workspace</small></div></div><nav>{items.map(([Icon, label]) => <button key={label} type="button" className={activePage === label ? 'active' : ''} onClick={() => onNavigate(label)}><Icon size={18} />{label}</button>)}</nav><div className="vendor-growth"><span>✦</span><strong>Ready to grow?</strong><p>Add products and start welcoming your first orders.</p><button type="button" onClick={onAddProduct}>Add your first product</button></div><button className="vendor-logout" type="button"><LogOut size={18} />Logout</button></aside> }
